import{_ as r,l as t,o as a,c as d,v as o,p as m,x as c,d as i,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"mmap 与页缓存一致","description":"","frontmatter":{"title":"mmap 与页缓存一致","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fs-mmap-coherence.md","filePath":"cs/fs-mmap-coherence.md","lastUpdated":1789023840000}'),l={name:"cs/fs-mmap-coherence.md"};function _(h,e,E,f,A,u){const s=t("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="mmap-与页缓存一致" tabindex="-1">mmap 与页缓存一致 <a class="header-anchor" href="#mmap-与页缓存一致" aria-label="Permalink to &quot;mmap 与页缓存一致&quot;">​</a></h1><div class="epigraph"><p>同一文件偏移应当对应同一页框：read、write 与 mmap 看见的是这一帧，而不是各持一份副本。</p><footer>—— 据 POSIX mmap；McKusick 对统一缓冲缓存的演进；Bovet and Cesati 对 address_space 的整理</footer></div><p><a href="/cs/fsck">上一课</a>保证盘上结构可检查。运行时另一条裂缝：<a href="/cs/page-cache">页缓存</a> 已说 read/mmap 共帧，但尚未钉 <strong>MAP_SHARED 写回、MAP_PRIVATE 写时复制、与 msync 的范围</strong>。缺口是一致性，不是再定义缺页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若 mmap 把设备块直接映射进进程，而 read 走另一套缓冲，同一偏移会有两份内容——这是历史教训。统一页缓存后：缺页从 inode 的页树取帧；<code>MAP_SHARED</code> 的写改这一帧并标脏；<code>MAP_PRIVATE</code> 在写时拷到匿名页，文件视图不变。缺口：<code>msync</code> 与 <code>fsync</code> 如何对齐；多进程共享映射时谁看见谁的写；<code>MAP_POPULATE</code> 只是预填，不改对象。</p><p><span class="marginnote"><code>MS_ASYNC</code> 只排队，<code>MS_SYNC</code> 等待稳定存储，语义靠近 fsync 的范围版。私有映射的脏匿名页不进文件 writeback。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>VFS：<code>mmap</code> 安装 vma，fault 调 <code>readpage</code>/<code>writepage</code> 同一套。写共享映射 = 改页缓存。<code>write</code> 系统调用也改同一页，于是编辑器 mmap 与后台 checksum 进程 read 不分裂。与 <a href="/cs/fsync">fsync</a>：对 fd 的 fsync 包含这些脏页。不要假设 <code>munmap</code> 等于 msync。</p>',8)),(a(),m(p,null,{default:c(()=>[n(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAULT%5B%22%E7%BC%BA%E9%A1%B5%22%5D%20--%3E%20TREE%5B%22inode%20%E9%A1%B5%E6%A0%91%22%5D%0A%20%20WRITE%5B%22write%20%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%20--%3E%20TREE%0A%20%20SH%5B%22MAP_SHARED%20%E5%AD%98%E5%82%A8%22%5D%20--%3E%20TREE%0A%20%20PR%5B%22MAP_PRIVATE%20%E5%86%99%22%5D%20--%3E%20ANON%5B%22%E5%8C%BF%E5%90%8D%E5%89%AF%E6%9C%AC%22%5D%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>共帧让「文件是字节数组」在虚存与系统调用之间成立。数据库用 <code>O_DIRECT</code> 故意绕过这一层，以免双重缓存——后课再讲。本课对象是默认路径。与 COW 文件系统：mmap 脏的是页缓存帧，下盘时仍走 FS 的 COW/日志，不在用户页表里完成树根切换。</p><p>不要把一致性写成 MESI：CPU 缓存一致性保证的是核间看见同一物理页；本课保证的是 VFS 不给同一偏移两份页框。</p><p>实现上：MAP_SHARED 的脏页与 writeback 共用 inode 页树，所以 msync 与 fsync 最终进同一套 writepages。MAP_PRIVATE 的匿名副本在换出时走 swap，不是文件空洞。 读法上只引用<a href="/cs/fsck">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>mmap 与页缓存一致</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 <code>userfaultfd</code> 的全部用户态填页——那是内存进阶。不保证 NFS 上 mmap 与远程写的缓存语义，那是 <a href="/cs/nfs-semantics">NFS</a> 课。下一课问文件逻辑大小里「没有块」的那些洞：稀疏与穿孔。</p><p>版本字段会变，课序钉的是机制对象「mmap 与页缓存一致」，不是某一主线内核的结构体名。 后课默认：共享映射与 read/write 共页缓存帧。逻辑空洞如何不占块、如何打孔归还，下一课稀疏文件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享 mmap 与读写共 inode 页树。</li><li>私有映射写时拷到匿名页；munmap 不是 msync。</li><li>稀疏与穿孔是下一课。</li><li>出处：POSIX mmap；McKusick；Bovet and Cesati, <em>ULK</em>；<em>OSTEP</em>。</li></ul>',11))])}const T=r(l,[["render",_]]);export{S as __pageData,T as default};
